#!/usr/bin/env bash
set -euo pipefail

repo="$(cd "$(dirname "$0")/.." && pwd)"
output="$repo/dist/AGENTS.md"

mkdir -p "$repo/dist"

# Codex can't import files, so it reads every rule from one generated file.
{
  echo "<!-- Generated by scripts/build.sh from global.md. Edit rules/, then rebuild. -->"
  sed -n 's/^@//p' "$repo/global.md" | while read -r path; do
    echo
    cat "$repo/$path"
  done
} >"$output"

echo "Built $output"
